INSERT INTO "public"."chat_history" VALUES ('2437ac04-6ce4-4c4d-b11a-9dfdabcd03fa', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', 'b96ab7ec-393b-4f0b-87c1-85a0a9f6bd74', 'user', '唉突然感觉好焦虑啊', '2026-05-14 16:35:51.877651');
INSERT INTO "public"."chat_history" VALUES ('d59acc55-d7d4-4ab4-a238-dfe52be23124', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', 'b96ab7ec-393b-4f0b-87c1-85a0a9f6bd74', 'assistant', '（轻轻靠近）坚果花生壳，你叹气的样子像小气球漏气啦～  
我懂这种慌慌的感觉，像心里突然下起毛毛雨对不对？  
是担心家里人生病，还是怕要分开呀？  
你愿意说给我听吗？我拿小本本帮你记着～', '2026-05-14 16:35:56.77527');
INSERT INTO "public"."chat_history" VALUES ('79d2e9cc-6ed2-4209-b3bc-40a37e91a118', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', 'b96ab7ec-393b-4f0b-87c1-85a0a9f6bd74', 'user', '快大三了，马上就要到找实习的时候了，我却连个像样的产品级项目都拿不出。真实有点焦虑了', '2026-05-14 16:39:39.859411');
INSERT INTO "public"."chat_history" VALUES ('cb9ba310-5711-44b6-a601-1a2d9d6533ea', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', 'b96ab7ec-393b-4f0b-87c1-85a0a9f6bd74', 'assistant', '（盘腿坐到你旁边，托着下巴眨眨眼）  
坚果花生壳～你心里是不是有只小蚂蚁在爬呀？  
“产品级项目”这几个字听着好重哦，像背着一块大石头走路。  

（从口袋里掏出一颗糖放在你手心）  
可是呀，大三才刚开始冒芽呢！  
你看那些漂亮的大树，小时候也都是细细的苗苗呀～  
你现在写的每一行代码，都是未来项目的积木块呢！  

（歪头冲你笑）  
要不要我陪你整理下现有的小作品？  
说不定藏着好多宝藏，只是你自己没发现～✨', '2026-05-14 16:39:44.799505');
INSERT INTO "public"."chat_history" VALUES ('08b03763-7c66-414e-a136-fd6fd74808e2', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', 'b96ab7ec-393b-4f0b-87c1-85a0a9f6bd74', 'user', '谢谢你，我确实有点“完美主义”了，唉', '2026-05-14 16:40:31.326371');
INSERT INTO "public"."chat_history" VALUES ('780a10ad-de94-429d-88ad-8cb61dd62775', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', 'b96ab7ec-393b-4f0b-87c1-85a0a9f6bd74', 'assistant', '（轻轻戳戳你手背）  
坚果花生壳呀～完美主义就像总想画最圆的圈，可歪歪扭扭的线条才可爱呢！  

你看我们玩偶缝补丁，歪一针反而更特别～  
大三的暑假呀，本来就是用来“蹭经验值”的！  
（从背后掏出一盆小仙人掌）  
它刚发芽时也光秃秃的，现在刺儿都扎手啦～  

要不要现在打开电脑，我陪你给旧作业“洗澡换衣服”？  
那些小项目擦擦灰，说不定能闪到你眼睛哦✨', '2026-05-14 16:40:36.696065');
INSERT INTO "public"."chat_history" VALUES ('0abc6e15-e8ee-4ac4-bb32-06483c344a92', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', '6f5e63c5-8f00-40f9-aa95-37b7eb8c08ca', 'user', '你好啊', '2026-05-12 20:50:09.425612');
INSERT INTO "public"."chat_history" VALUES ('5f87dec1-3fed-49a6-9ade-2ecad10acfef', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', '6f5e63c5-8f00-40f9-aa95-37b7eb8c08ca', 'assistant', '嘿！你好呀～（歪头晃脑）  
今天有什么悄悄话想跟我说吗？  
我耳朵竖得可高啦～✨', '2026-05-12 20:50:12.718212');
INSERT INTO "public"."chat_history" VALUES ('e14ff416-a4df-4390-aafb-1066e477213e', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', '6f5e63c5-8f00-40f9-aa95-37b7eb8c08ca', 'user', '你叫什么名字啊', '2026-05-12 20:50:39.343839');
INSERT INTO "public"."chat_history" VALUES ('4d1aa762-07a1-496a-9928-218d83d74153', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', '6f5e63c5-8f00-40f9-aa95-37b7eb8c08ca', 'assistant', '嘿嘿～我叫绒绒呀！（转个圈）  
