INSERT INTO "public"."chat_history" VALUES ('785af961-f683-4c4b-9fa0-ba8915712e72', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', '6f5e63c5-8f00-40f9-aa95-37b7eb8c08ca', 'user', '嗯，你叫我坚果花生壳吧', '2026-05-12 20:51:18.933343');
INSERT INTO "public"."chat_history" VALUES ('62c61d51-5df6-44f3-bfd8-14d72e33bf7d', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', '6f5e63c5-8f00-40f9-aa95-37b7eb8c08ca', 'assistant', '（拍拍手）好有趣的称呼！  
