INSERT INTO "public"."chat_history" VALUES ('c96cfbb8-a434-4889-a62f-d0db356d2756', '3f7e4b2c-8a9d-4f1e-9c2b-6a5d4e3f2a1b', '6f5e63c5-8f00-40f9-aa95-37b7eb8c08ca', 'user', '不要了，就叫全名吧', '2026-05-12 20:52:02.019255');
